export function buildChecklist(form,products){
 const cpu=products.find(p=>p.id===form.targetCpu),gpu=products.find(p=>p.id===form.targetGpu),items=[];
 const add=(status,title,text)=>items.push({status,title,text});
 if(cpu){if(form.socket&&form.socket!==cpu.socket)add('Change required','Motherboard platform',`${cpu.name} requires ${cpu.socket}; your entered socket is ${form.socket}. The existing motherboard cannot accept this processor.`);else add('Verify','Motherboard and BIOS',`Check the exact motherboard model’s CPU support list and minimum BIOS for ${cpu.name}. ${cpu.socket} alone does not confirm support.`);
 if(form.ramType&&cpu.memoryType&&!cpu.memoryType.includes(form.ramType))add('Change required','Memory generation',`${cpu.name} supports ${cpu.memoryType}; your ${form.ramType} memory is not supported.`);else add('Likely reusable','Memory',`${form.ramType||'Existing'} memory may be reusable if the board supports that type, capacity and configuration. Check its memory QVL; DDR4 and DDR5 slots are not interchangeable.`);
 add('Verify','CPU cooler',`Confirm ${cpu.socket} mounting hardware, cooler clearance and cooling capacity. ${cpu.powerLabel}: ${cpu.power} W is a manufacturer rating, not measured whole-system power.`);
 if(cpu.igpu===false&&!gpu&&!form.existingGpu)add('Change required','Display adapter','This CPU has no integrated graphics. A discrete graphics card is needed for display output.');
 }
 if(gpu){add('Verify','Power supply and cables',`${form.psu||'Your PSU'} needs an exact model and cable check against the board partner’s requirements. The ${gpu.name} ${gpu.powerLabel} is ${gpu.power} W. Wattage alone does not establish PSU suitability; never mix modular cables from different PSU models.`);add('Verify','Case and PCIe slot',`Check the exact card length, thickness, slot access and power-cable bend clearance${form.clearance?` against your entered ${form.clearance} mm clearance`:''}. Board-partner dimensions vary. Check motherboard slot support.`);add('Likely reusable','Monitor',`${form.monitor||'Your monitor'} may remain usable with a matching display input and suitable cable. Resolution and refresh-rate support must be checked for the exact card and output.`)}
 add('Unavailable','Performance evidence',`No comparable benchmark dataset is included for ${form.use||'your workload'}. Existing ${[form.existingCpu,form.existingGpu].filter(Boolean).join(' / ')||'hardware'} and a ${form.budget||'not specified'} budget do not justify a predicted FPS or bottleneck percentage. Consult matched application or game tests.`);
 if(!cpu&&!gpu)add('Verify','Choose target parts','Select at least one target CPU or GPU to generate part-specific requirements.');return items;
}
